import heapq

def find_n_largest(numbers, n):
    if n <= 0:
        return []
    # Use heapq to find the n largest numbers
    largest_numbers = heapq.nlargest(n, numbers)
    # Return them sorted in descending order
    return sorted(largest_numbers, reverse=True)
